'use strict';
const $ = (id)=>document.getElementById(id);
const esc = (v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n=>Number(n??0).toLocaleString('en-GB',{maximumFractionDigits:2});
const money = n=>'GBP '+Number(n??0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2});
const stamp = () => new Date().toLocaleDateString('en-GB',{year:'numeric',month:'short',day:'numeric'});
const lastMonday=()=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return d.toISOString().slice(0,10)};
const later=(d=7)=>new Date(Date.now()+d*86400000).toISOString().slice(0,10);
const ago = s=>s?new Date(s).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'--';
const initials=s=>(s||'SC').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const state={user:null,page:'overview',public:false,persona:[],candidateToken:localStorage.getItem('sheffield_candidate_token')||'',report:{group:'department',metric:'headcount',filter:''}};
const R={employee:'Employee',manager:'Hiring / team manager',hr:'People Services',payroll:'Payroll',learning:'Learning administrator',service:'Service manager',admin:'System administrator',recruiter:'Recruiter'};
const NAV=[
 ['overview','Overview','&#9635;'],['profile','My profile','&#9787;'],['leave','Absence & leave','&#9719;'],['time','Time & attendance','&#9201;'],['org','Organisation','&#9783;'],
 ['recruit','Recruitment & onboarding','&#9659;'],['documents','Document records','&#9638;'],
 ['tasks','HR journeys & tasks','&#9745;'],['learning','Learning hub','&#9734;'],
 ['payroll','Payroll & payslips','&#163;'],['reports','Workforce insights','&#9685;'],
 ['optional','Optional capabilities','&#9881;'],['integrations','Integration control','&#8644;'],
 ['messages','Private messaging','&#9993;']];
const NAV2=[['guide','Demo walkthrough','&#9654;'],['matrix','Requirements matrix','&#9636;'],['audit','Audit evidence','&#8801;']];
const permissions={
 profile:[],time:[],leave:[],org:[],recruit:[],documents:[],tasks:[],learning:[],payroll:[],reports:['manager','service','hr','payroll','recruiter','learning','admin'],
 optional:[],integrations:['admin','hr'],messages:[],guide:[],matrix:[],audit:['admin','hr','service','payroll']};
const can=(page)=>!permissions[page]||!permissions[page].length||permissions[page].includes(state.user?.role);
const elevated=()=>['hr','admin','recruiter'].includes(state.user?.role);
const isHR=()=>['hr','admin'].includes(state.user?.role);
const isManager=()=>['manager','hr','admin'].includes(state.user?.role);
function status(v){const t=String(v??''),good=/approved|complete|onboarded|finalised|published|delivered|accepted|booked/i.test(t),bad=/reject|withdraw|failed|closed/i.test(t),warn=/pending|draft|queued|submitted|offered/i.test(t);return `<span class="badge ${good?'good':bad?'bad':warn?'warn':'blue'}">${esc(t)}</span>`}
function toast(msg,err=false){const t=$('toast');t.textContent=msg;t.className='toast show'+(err?' bad':'');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>t.className='toast',4200)}
async function api(path,options={}){let opts={credentials:'same-origin',...options};if(opts.body&&!(opts.body instanceof FormData)&&typeof opts.body!=='string'){opts.headers={'Content-Type':'application/json',...(opts.headers||{})};opts.body=JSON.stringify({data:opts.body});}
 const res=await fetch('/api'+path,opts);let out=await res.json().catch(()=>({}));if(!res.ok){if(res.status===401&&path!=='/login'){await showLogin();}throw new Error(out.error||`Request failed (${res.status})`)}return out}
const post=(path,data={})=>api(path,{method:'POST',body:data});
function formData(form){const v=Object.fromEntries(new FormData(form).entries());for(let c of form.querySelectorAll('input[type=checkbox]')){if(c.name)v[c.name]=c.checked;}return v}
function pageHead(title,kicker,desc,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="head-actions">${buttons}</div></div>`}
function loading(s='Loading connected records...'){return `<div class="card"><div class="blank-state"><div class="empty-icon">&#9684;</div>${esc(s)}</div></div>`}
function table(headers,list,render){return `<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${list.length?list.map(render).join(''):`<tr><td colspan="${headers.length}"><div class="blank-state"><span class="empty-icon">&#9711;</span><strong>No records yet</strong>Try completing a transaction to see connected data here.</div></td></tr>`}</tbody></table></div>`}
const selectOpts=(items, val='id',label='name',selected='')=>items.map(a=>`<option value="${esc(a[val])}" ${String(a[val])===String(selected)?'selected':''}>${esc(a[label])}</option>`).join('');
function openModal(title,intro,contents){$('modalRoot')?.remove();const d=document.createElement('div');d.id='modalRoot';d.className='modal-cover';d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><button class="modal-close" data-act="close-modal" aria-label="Close">&times;</button><h2 id="modalTitle">${esc(title)}</h2><p>${esc(intro)}</p>${contents}</section>`;document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target===d)d.remove()});d.querySelector('input,select,textarea')?.focus();}
const closeModal=()=>$('modalRoot')?.remove();
function go(page){if(!can(page)&&!state.public)return toast('This work area is restricted for your demo persona.',true);state.page=page;document.querySelector('.sidebar')?.classList.remove('open');render();}
function navRender(){const item=([key,title,icon])=>`<button type="button" class="navlink ${state.page===key?'active':''}" data-page="${key}"><span class="nav-symbol">${icon}</span>${esc(title)}</button>`;
 $('nav').innerHTML=NAV.filter(([key])=>can(key)).map(item).join('');$('nav2').innerHTML=NAV2.filter(([key])=>can(key)).map(item).join('');}
function setLayout(){if(state.public){$('login').hidden=true;$('workspace').hidden=false;$('sidebar').hidden=true;document.querySelector('.main-area').style.marginLeft='0';document.querySelector('.main-area').style.width='100%';$('userName').textContent='Public careers';$('userRole').textContent='Candidate portal';$('avatar').textContent='CP';}
 else{$('login').hidden=true;$('workspace').hidden=false;$('sidebar').hidden=false;document.querySelector('.main-area').style.marginLeft='';document.querySelector('.main-area').style.width='';$('userName').textContent=state.user?.name||'Guest';$('userRole').textContent=R[state.user?.role]||'';$('avatar').textContent=initials(state.user?.name);navRender();}
 $('stamp').textContent=stamp()}
async function showLogin(){state.user=null;state.public=false;closeModal();$('login').hidden=false;$('workspace').hidden=true;try{const people=await api('/personas');state.persona=people;$('personaSelect').innerHTML=people.map(p=>`<option value="${p.id}">${esc(p.name)} - ${esc(R[p.role])}</option>`).join('')}catch(e){toast(e.message,true)}}
async function boot(){try{const info=await api('/me');state.user=info.user;setLayout();await render();}catch(e){await showLogin();}}
async function render(){if(!state.user&&!state.public)return;setLayout();$('crumb').textContent=state.public?'Public careers':([NAV,...[NAV2]].flat().find(x=>x[0]===state.page)||[,'Overview'])[1];$('content').innerHTML=loading();try{
  const routes={overview:overview,profile:profile,time:timesheets,leave:leave,org:org,recruit:recruit,documents:documents,tasks:tasks,learning:learning,payroll:payroll,reports:reports,optional:optional,integrations:integrations,messages:messages,guide:guide,matrix:matrix,audit:audit};
  if(state.public){$('content').innerHTML=await careers();return;}if(routes[state.page])$('content').innerHTML=await routes[state.page]();
 }catch(e){$('content').innerHTML=`${pageHead('Something needs attention','RETRYABLE ERROR','The request did not complete. No success has been assumed.')}<div class="note error">${esc(e.message)}</div><p><button class="btn ghost" data-act="refresh">Try again</button></p>`;toast(e.message,true)}}
async function overview(){const x=await api('/dashboard');const cards=[['People records',fmt(x.headcount),'Synthetic sample, not entire workforce'],['Approvals pending',fmt(x.pending_leave),'Updated from leave transactions'],['Assigned tasks',fmt(x.open_tasks),'Actionable workflow assignments'],['Applications',fmt(x.applications),'Applicant pipeline records']];
 const ways=[['leave','Book and approve leave','Employee to manager approval, audit and balance'],['org','Explore organisation','Manager spans, position attributes and FTE'],['recruit','Recruit a new colleague','Vacancy, candidate, interview, offer and onboarding'],['documents','Manage employee records','Upload, retention policy, archive and purge'],['tasks','Complete an HR journey','Task ownership, exceptions and audit trail'],['reports','Explore workforce insights','Filters, role-aware metrics and CSV export']];
 return `${pageHead('Your connected workplace','OVERVIEW / LIVE WORKSPACE',`Welcome, ${state.user.name.split(' ')[0]}. Every completed demo action updates the shared data model.`)}
  <div class="hero-strip"><div><div class="caps">SHEFFIELD CITY COUNCIL / REFERENCE 100113345</div><h2>From first application to employee success.</h2><p>One role-aware experience. Live transactions, decisions and evidence across Sheffield's six priority journeys.</p></div><button class="btn" data-page="guide">Start guided demo &rarr;</button></div>
  <div class="grid four">${cards.map(([a,b,c])=>`<div class="card stat"><div class="stat-label">${a}</div><div class="stat-num mono">${b}</div><div class="stat-foot"><span class="stat-dot"></span>${c}</div></div>`).join('')}</div>
  <div class="section-top" style="margin-top:29px"><h2>Explore a complete journey</h2><span>Six Sheffield demonstration use cases</span></div>
  <div class="path-grid">${ways.map(([id,a,b],i)=>`<button class="path-card" data-page="${id}"><span class="path-icon">${['&#9719;','&#9783;','&#9673;','&#9638;','&#9745;','&#9685;'][i]}</span><strong>${a}</strong><span>${b}</span></button>`).join('')}</div>
  <div class="grid two" style="margin-top:20px"><div class="card"><div class="section-top"><h2>Recent activity</h2><span>Audited actions</span></div><div class="timeline">${x.activity.length?x.activity.map(a=>`<div class="timeline-item"><div class="timeline-bullet"></div><div><strong>${esc(a.actor)} ${esc(a.action.replaceAll('-',' '))}</strong><div class="small muted">${esc(a.entity)} #${esc(a.entity_id)}${a.detail?' / '+esc(a.detail):''}</div><small>${ago(a.created)}</small></div></div>`).join(''):'No activity recorded yet'}</div></div>
  <div class="card"><h2>Solution evidence snapshot</h2><p class="card-sub">Proposal mapping from the submitted PME response</p><div class="grid two"><div class="metric-teaser"><strong style="font-size:29px">47</strong><div class="small muted">Process requirements</div></div><div class="metric-teaser"><strong style="font-size:29px">43 / 4</strong><div class="small muted">Base / additional cost</div></div><div class="metric-teaser"><strong style="font-size:29px">6</strong><div class="small muted">Priority scenarios</div></div><div class="metric-teaser"><strong style="font-size:29px">8,000</strong><div class="small muted">Pricing population baseline</div></div></div><div class="note attention" style="margin-top:16px"><span class="warning-dot"></span>${esc(x.note)}</div></div></div>`}
async function profile(){const x=await api('/profile');return `${pageHead('My employee profile','EMPLOYEE SELF-SERVICE / PERSONAL INFORMATION','Review your position and update your own contact details, with an audit record.',`<button class="btn primary" data-act="profile-edit">Edit contact details</button>`)}<div class="grid two"><div class="card"><div class="eyebrow">CURRENT POSITION</div><div class="row" style="margin-bottom:22px"><div class="avatar" style="height:56px;width:56px;font-size:20px">${initials(x.user.name)}</div><div><h2>${esc(x.user.name)}</h2><div class="small muted">${esc(x.user.job)}</div></div></div>${[['Department',x.user.department],['Grade',x.user.grade],['Cost centre',x.user.cost_center],['Full-time equivalent',fmt(x.user.fte)],['Email',x.user.email]].map(a=>`<div class="row space" style="padding:12px 0;border-bottom:1px solid #eaf0f5"><span class="muted">${a[0]}</span><strong class="small">${esc(a[1])}</strong></div>`).join('')}</div><div class="card"><div class="eyebrow">CONTACT DETAILS</div><h3>Your personal information</h3><p class="card-sub">Changes are persisted to the same employee identity used across the demo.</p>${[['Telephone',x.profile.phone||'Not provided'],['Address',x.profile.address||'Not provided'],['Emergency contact',x.profile.emergency_contact||'Not provided']].map(a=>`<div style="padding:16px 0;border-bottom:1px solid #eaf0f5"><div class="micro muted">${a[0]}</div><strong>${esc(a[1])}</strong></div>`).join('')}</div></div>`}
async function timesheets(){const x=await api('/time');return `${pageHead('Time & attendance','STANDARD SCOPE / WEEKLY TIMESHEETS','Submit hours, review team timesheets and approve time to the mock finance interface.',`<button class="btn primary" data-act="new-time">+ Submit timesheet</button>`)}<div class="card"><div class="section-top"><h2>Weekly submissions</h2><span>One entry per employee/week; all decisions audited</span></div>${table(['Employee','Week commencing','Hours','State','Decision'],x,a=>`<tr><td><strong>${esc(a.employee)}</strong></td><td>${esc(a.week_start)}</td><td>${fmt(a.hours)}</td><td>${status(a.status)}</td><td>${a.status==='Submitted'&&((state.user.role==='manager'&&a.manager_id===state.user.id)||isHR())?`<span class="inline-actions"><button class="btn light small" data-act="time-decision" data-id="${a.id}" data-choice="Approved">Approve</button><button class="btn ghost small" data-act="time-decision" data-id="${a.id}" data-choice="Rejected">Reject</button></span>`:'--'}</td></tr>`)}</div><div class="note" style="margin-top:18px">This demonstrates approval workflow, not a licensed statutory time/payroll engine. Specific Sheffield overtime and shift rules will need separate configuration and validation.</div>`}

async function leave(){const x=await api('/leave');return `${pageHead('Leave & absence','USE CASE 01 / EMPLOYEE SELF-SERVICE','View entitlement components, submit an absence and watch a manager decision update the same record.',`<button class="btn primary" data-act="new-leave">+ Request leave</button>`)}
 <div class="grid four"><div class="card stat"><div class="stat-label">Available annual leave</div><div class="stat-num">${fmt(x.balance)} <small style="font-size:14px">days</small></div><div class="stat-foot">Approved requests reduce your balance</div></div>${[['Annual entitlement',x.entitlement.annual],['Carry forward + purchased',x.entitlement.carry_forward+x.entitlement.purchased],['Bank holiday allocation',x.entitlement.bank_holidays]].map(a=>`<div class="card stat"><div class="stat-label">${a[0]}</div><div class="stat-num">${fmt(a[1])}</div><div class="stat-foot">Council policy demo setting</div></div>`).join('')}</div>
 <div class="card" style="margin-top:20px"><div class="section-top"><h2>Requests & decisions</h2><span>History is live and audit-backed</span></div>${table(['Employee','Type','Dates','Days','Status','Decision'],x.items,a=>`<tr><td><strong>${esc(a.employee)}</strong></td><td>${esc(a.leave_type)}</td><td>${esc(a.start)} to ${esc(a.ending)}</td><td>${fmt(a.days)}</td><td>${status(a.status)}</td><td class="actions">${a.status==='Pending'&&((state.user.role==='manager'&&a.manager_id===state.user.id)||isHR())?`<span class="inline-actions"><button class="btn small light" data-act="leave-decision" data-id="${a.id}" data-choice="Approved">Approve</button><button class="btn small ghost" data-act="leave-decision" data-id="${a.id}" data-choice="Rejected">Reject</button></span>`:'--'}</td></tr>`)}</div>
 <div class="note" style="margin-top:17px">Switch from <strong>Aisha Khan</strong> to <strong>Helen Walker</strong> using Change persona after submitting leave to approve or reject it. Overlapping leave requests and insufficient entitlement are blocked.</div>`}
async function org(){const x=await api('/org');const nodes=x.people;return `${pageHead('Organisation & position hierarchy','USE CASE 02 / ESTABLISHMENT','Review the management structure and post attributes, with live headcount and FTE roll-ups.')}
 <div class="card"><div class="section-top"><h2>Reporting lines</h2><span>${nodes.length} visible positions under your security profile</span></div><div class="org-row">${nodes.map(p=>`<div class="org-node"><strong>${esc(p.name)}</strong><small>${esc(p.job)} / ${esc(p.grade)}</small><div class="row space" style="margin-top:12px"><span class="micro muted">${esc(p.department)}</span>${status('FTE '+fmt(p.fte))}</div><small>Cost centre ${esc(p.cost_center)}</small><small>Reports to: ${esc(nodes.find(n=>n.id===p.manager_id)?.name||'Protected / top of hierarchy')}</small></div>`).join('')}</div></div>
 <div class="card" style="margin-top:19px"><div class="section-top"><h2>Establishment summary</h2><span>Aggregates update when a candidate becomes a worker</span></div>${x.rollups.length?table(['Directorate / service','Cost centre','Headcount','Total FTE'],x.rollups,r=>`<tr><td><strong>${esc(r.department)}</strong></td><td>${esc(r.cost_center)}</td><td>${fmt(r.headcount)}</td><td>${fmt(r.fte)}</td></tr>`):'<div class="note">Detailed cost-centre roll-ups require manager, service or HR permissions.</div>'}</div>`}
function careersTable(v){return `<div class="grid two">${v.filter(x=>x.status==='Published').map(a=>`<div class="card"><div class="row space"><div class="eyebrow">${esc(a.department)}</div>${status(a.status)}</div><h2>${esc(a.title)}</h2><p class="small muted">${esc(a.location)} &nbsp; / &nbsp; ${esc(a.grade)} &nbsp; / &nbsp; ${esc(a.salary)}</p><p style="min-height:50px">${esc(a.summary)}</p><div class="row space" style="margin-top:19px"><span class="small muted">Closes ${esc(a.closing)}</span><button class="btn primary small" data-act="apply" data-id="${a.id}" data-title="${esc(a.title)}" data-cover="${a.cover_required}">Apply for role &rarr;</button></div></div>`).join('')||'<div class="card">There are no published vacancies yet.</div>'}</div>`}
async function careers(){const v=await api('/vacancies');let track='';if(state.candidateToken){try{const a=await api('/candidate/'+encodeURIComponent(state.candidateToken));track=`<div class="card" style="margin-bottom:20px"><div class="row space"><div><div class="eyebrow">YOUR APPLICATION TRACKER</div><h3>${esc(a.vacancy)}</h3><p class="small muted">Applicant: ${esc(a.name)}</p></div>${status(a.stage)}</div><div class="steps" style="margin-top:18px">${['Applied','Shortlisted','Interview Scheduled','Interview Completed','Offered','Offer Accepted','Checks Complete','Onboarded'].map((s,i,arr)=>`<span class="step-pill ${arr.indexOf(a.stage)>=i?'done':''}">${s}</span>`).join('')}</div>${['Shortlisted','Interview Scheduled'].includes(a.stage)?`<div class="row wrap" style="margin-top:16px"><button class="btn primary small" data-act="schedule">${a.interview_slot?'Reschedule interview':'Choose interview slot'}</button><span class="small muted">${a.interview_slot?ago(a.interview_slot)+' / '+a.interview_type:'Choose a future time for interview'}</span></div>`:''}<div class="row wrap" style="margin-top:12px">${!['Onboarded','Rejected','Withdrawn'].includes(a.stage)?'<button class="btn small danger" data-act="withdraw">Withdraw application</button>':''}<button class="btn small ghost" data-act="clear-candidate">Track a different application</button></div></div>`;const events=await api('/candidate/'+encodeURIComponent(state.candidateToken)+'/messages');track+=`<div class="card" style="margin-bottom:20px"><h3>Updates & correspondence</h3><p class="small muted">Candidate-only portal inbox; any message from a recruiter appears below without claiming external email delivery.</p>${events.map(m=>`<div style="padding:12px 0;border-bottom:1px solid #e5edf4"><div class="row space"><strong>${esc(m.title)}</strong><span class="micro muted">${ago(m.created)}</span></div><p>${esc(m.body)}</p></div>`).join('')||'<p>No correspondence yet.</p>'}</div>`;}catch(e){track='<div class="note error">Saved application token is no longer valid. You can enter a new token below.</div>'}}
 return `<div class="page-head"><div><div class="eyebrow">SHEFFIELD / PUBLIC CANDIDATE EXPERIENCE</div><h1>Your next role starts here.</h1><p>Clear applications, transparent progress and self-selected interviews in a mobile-friendly experience.</p></div><button class="btn ghost" data-act="public-exit">${state.user?'Return to workspace':'Staff sign in'}</button></div><div class="hero-strip"><div><h2>Make a difference across Sheffield.</h2><p>Explore service opportunities and follow each step from application to offer.</p></div><span style="font-size:34px;opacity:.7">&#9734;</span></div>${track}<div class="section-top"><h2>Open opportunities</h2><span>Published roles only</span></div>${careersTable(v)}<div class="card" style="margin-top:20px"><h3>Already applied?</h3><p class="card-sub">Enter the secure application tracking token you received after submitting.</p><form data-form="candidate-lookup" class="input-row"><label>Application access code<input name="token" value="${esc(state.candidateToken)}" required placeholder="Paste your application token"></label><button class="btn light" type="submit">View progress</button></form></div>`}
async function recruit(){const v=await api('/vacancies');let a=[];if(elevated()||state.user.role==='manager'){a=await api('/applications')}
 let b=`${pageHead('Recruitment & onboarding','USE CASE 03 / APPLICANT TO WORKER','Short vacancy creation, candidate progress, interview feedback, offer and a shared employee record.',`${isManager()||state.user.role==='recruiter'?'<button class="btn primary" data-act="new-vacancy">+ Create vacancy</button>':''}<button class="btn ghost" data-act="public-careers">Preview career portal</button>`)}
 <div class="card"><div class="section-top"><h2>Vacancy management</h2><span>One-page manager journey with editable revisions</span></div>${table(['Vacancy','Service','Grade / location','Status','Version','Actions'],v,x=>`<tr><td><strong>${esc(x.title)}</strong><div class="micro muted">Closes ${esc(x.closing)}</div></td><td>${esc(x.department)}</td><td>${esc(x.grade)} / ${esc(x.location)}</td><td>${status(x.status)}</td><td>v${x.revision}</td><td class="actions"><div class="inline-actions">${(isManager()||state.user.role==='recruiter')?`<button class="btn small ghost" data-act="edit-vacancy" data-id="${x.id}">Edit</button>`:''}${elevated()&&x.status==='Draft'?`<button class="btn small light" data-act="publish" data-id="${x.id}">Publish</button>`:''}${elevated()&&x.status==='Published'?`<button class="btn small danger" data-act="close-vacancy" data-id="${x.id}">Close</button>`:''}</div></td></tr>`)}</div>`;
 b+=`<div class="card" style="margin-top:20px"><div class="section-top"><h2>Candidate pipeline</h2><span>Recorded shortlisting and interview outcomes</span></div>${table(['Candidate / vacancy','Stage','Interview','Feedback','Next action'],a,x=>`<tr><td><strong>${esc(x.name)}</strong><div class="micro muted">${esc(x.vacancy)}</div></td><td>${status(x.stage)}</td><td>${x.interview_slot?ago(x.interview_slot):'Not yet booked'}</td><td>${x.interview_feedback?esc(x.interview_feedback):'--'}${x.interview_score!==null&&x.interview_score!==undefined?`<div class="micro">Score ${x.interview_score}/5</div>`:''}</td><td class="actions"><div class="inline-actions">${nextStage(x)}<button class="btn ghost small" data-act="app-message" data-id="${x.id}">Message</button></div></td></tr>`)}</div><div class="note" style="margin-top:17px">Candidate interview selection/rescheduling, mandatory cover letters, application status and detailed selection feedback have been included in response to the separate opportunity feedback. Delivery of invitation email to Outlook is represented by a mock integration queue.</div>`;
 return b}
function nextStage(a){const nxt={'Applied':['Shortlisted','Rejected'],'Shortlisted':[],'Interview Scheduled':['Interview Completed','Rejected'],'Interview Completed':['Offered','Rejected'],'Offered':['Offer Accepted','Rejected'],'Offer Accepted':['Checks Complete'],'Checks Complete':['Onboarded']};return (nxt[a.stage]||[]).map(s=>`<button class="btn small ${s==='Rejected'?'danger':'light'}" data-act="app-stage" data-id="${a.id}" data-stage="${esc(s)}">${esc(s)}</button>`).join(' ')||'<span class="micro muted">Awaiting candidate / completed</span>'}
async function documents(){const docs=await api('/documents');const people=await api('/people');return `${pageHead('Employee document records','USE CASE 04 / DOCUMENT GOVERNANCE','Controlled upload, classified records, employee visibility, retention and scheduled archive/purge.',`<button class="btn primary" data-act="new-document">+ Upload document</button>`)}
 <div class="grid two"><div class="card"><div class="eyebrow">SAFE RECORD STORAGE</div><h3>Confidential employee files</h3><p class="small muted">Only employees and authorised People Services can access documents. Every view and upload is audited.</p></div><div class="card"><div class="eyebrow">RETENTION CONTROL</div><h3>Archive before eligible purge</h3><p class="small muted">Purge requires both expiry of the retention date and archive status, with a recorded audit event.</p></div></div>
 <div class="card" style="margin-top:20px"><div class="section-top"><h2>Document register</h2>${isHR()?'<button class="btn small ghost" data-act="purge">Run eligible purge</button>':''}</div>${table(['File / employee','Type','Retention until','Record state','Actions'],docs,a=>`<tr><td><a href="/api/documents/${a.id}/download" target="_blank" rel="noopener">${esc(a.name)}</a><div class="micro muted">${esc(a.employee)}</div></td><td>${esc(a.doc_type)}</td><td>${esc(a.retention_until)}</td><td>${status(a.archived?'Archived':'Active')}</td><td>${isHR()&&!a.archived?`<button class="btn ghost small" data-act="archive" data-id="${a.id}">Archive</button>`:state.user.role==='admin'&&a.archived?`<button class="btn light small" data-act="doc-expire" data-id="${a.id}">Simulate expiry</button>`:'--'}</td></tr>`)}</div><div class="note" style="margin-top:15px">This prototype enforces role-based file access and retention transitions locally. Formal GDPR compliance, legal holds, production encryption, and retention policy validation require a deployed implementation.</div>`}
async function tasks(){const t=await api('/tasks');return `${pageHead('HR journeys & task control','USE CASE 05 / PEOPLE SERVICES','Clearly owned work, manager/employee actions, HR checks and permanent audit history.',`${isManager()||state.user.role==='learning'?'<button class="btn primary" data-act="new-task">+ Assign task</button>':''}`)}<div class="grid two"><div class="card"><h3>Actionable task queue</h3><p class="card-sub">Role-assigned actions appear automatically after hiring and during HR processes.</p><strong style="font:800 38px Manrope">${t.filter(x=>x.status==='Open').length}</strong><div class="small muted">Open tasks in this view</div></div><div class="card"><h3>Connected hand-off</h3><p class="card-sub">An onboarded candidate creates tasks for employee, People Services and Learning, without re-entering a separate employee identity.</p><button class="btn small light" data-page="recruit">See recruiting journey &rarr;</button></div></div>
 <div class="card" style="margin-top:20px">${table(['Task','Workstream','Owner','Deadline','State','Action'],t,x=>`<tr><td><strong>${esc(x.title)}</strong><div class="micro muted">${esc(x.notes||'')}</div></td><td>${esc(x.kind)}</td><td>${esc(x.owner||'')}</td><td>${esc(x.due||'')}</td><td>${status(x.status)}</td><td>${x.status==='Open'?`<button class="btn small light" data-act="task-done" data-id="${x.id}">Complete</button>`:'--'}</td></tr>`)}</div>`}
async function learning(){const x=await api('/learning');return `${pageHead('Learning & development','LEARNING / CONNECTED EMPLOYEE RECORD','Search available courses, enrol, record completion, and view team learning activity.')}
 <div class="grid two">${x.courses.map(c=>`<div class="card"><div class="row space"><span class="badge blue">${esc(c.category)}</span><span class="small muted">${fmt(c.hours)} learning hours</span></div><h3 style="margin-top:15px">${esc(c.title)}</h3><p class="small muted">${esc(c.description)}</p><div class="row space" style="margin-top:20px"><span class="small muted">${c.booked} / ${c.seats} enrolled</span><button class="btn light small" data-act="enrol" data-id="${c.id}" ${x.enrolments.some(e=>e.course_id===c.id&&e.employee_id===state.user.id)?'disabled':''}>${x.enrolments.some(e=>e.course_id===c.id&&e.employee_id===state.user.id)?'Already enrolled':'Book course'}</button></div></div>`).join('')}</div>
 <div class="card" style="margin-top:20px"><div class="section-top"><h2>Learning records</h2><span>Self and permitted team activity</span></div>${table(['Person','Course','Booked','Status','Action'],x.enrolments,e=>`<tr><td><strong>${esc(e.employee)}</strong></td><td>${esc(e.course)}</td><td>${ago(e.created)}</td><td>${status(e.status)}</td><td>${e.status==='Enrolled'?`<button class="btn light small" data-act="learning-complete" data-id="${e.id}">Record completion</button>`:'--'}</td></tr>`)}</div>`}
async function payroll(){const x=await api('/payroll');return `${pageHead('Payroll & employee payslips','UK PAYROLL / EXPLAINABLE SIMULATOR','Run an illustrative monthly calculation, finalise a period and view a connected employee payslip.',`${['payroll','admin'].includes(state.user.role)?'<button class="btn primary" data-act="new-payroll">+ Create payroll run</button>':''}`)}<div class="note attention"><strong>Non-statutory payroll simulation:</strong> applies a fixed illustrative 18% deduction to synthetic salaries. It does not perform actual UK PAYE, NI, LGPS/TPS, RTI, P60 or P45 calculations. No payments are sent.</div>
 ${x.runs.length?`<div class="card" style="margin-top:17px"><h3>Payroll control centre</h3>${table(['Period','People','Gross pay','Demo deductions','Net pay','Status','Action'],x.runs,r=>`<tr><td><strong>${esc(r.period)}</strong></td><td>${r.headcount}</td><td>${money(r.gross)}</td><td>${money(r.deduction)}</td><td>${money(r.net)}</td><td>${status(r.status)}</td><td>${r.status==='Draft'?`<button class="btn light small" data-act="pay-final" data-id="${r.id}">Finalise</button>`:'--'}</td></tr>`)}</div>`:''}
 <div class="card" style="margin-top:18px"><h3>My payslips</h3><p class="card-sub">Payslips become available only after the payroll administrator finalises a period.</p>${table(['Period','Gross','Demo deduction','Net','Status'],x.payslips,r=>`<tr><td><strong>${esc(r.period)}</strong></td><td>${money(r.gross)}</td><td>${money(r.deduction)}</td><td><strong>${money(r.net)}</strong></td><td>${status(r.status)}</td></tr>`)}</div>`}
async function reports(){const q=new URLSearchParams(state.report);const x=await api('/reports?'+q.toString());const max=Math.max(1,...x.items.map(v=>v.value));return `${pageHead('Workforce insights','USE CASE 06 / MANAGEMENT INFORMATION','Build your own summary using safe filters, drill into service aggregates and export the result.',`<button class="btn ghost" data-act="csv">Export CSV &darr;</button>`)}
 <div class="card"><form data-form="report" class="field-grid" style="grid-template-columns:1fr 1fr 1fr auto;align-items:end"><label>Group by<select name="group"><option value="department" ${state.report.group==='department'?'selected':''}>Service / department</option><option value="cost_center" ${state.report.group==='cost_center'?'selected':''}>Cost centre</option><option value="grade" ${state.report.group==='grade'?'selected':''}>Pay grade</option></select></label><label>Measure<select name="metric"><option value="headcount" ${state.report.metric==='headcount'?'selected':''}>Headcount</option><option value="fte" ${state.report.metric==='fte'?'selected':''}>FTE</option>${['admin','hr','payroll','service'].includes(state.user.role)?'<option value="salary" '+(state.report.metric==='salary'?'selected':'')+'>Annual pay (restricted)</option>':''}</select></label><label>Find / filter<input name="filter" value="${esc(state.report.filter)}" placeholder="e.g. Social Care"></label><button class="btn primary" type="submit">Apply filters</button></form></div>
 <div class="grid two" style="margin-top:20px"><div class="card"><div class="section-top"><h2>Live workforce distribution</h2><span>${x.items.length} groups</span></div><div class="report-bars">${x.items.length?x.items.map(a=>`<div class="report-bar"><span class="ellipsis" title="${esc(a.label)}">${esc(a.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,(a.value/max)*100)}%"></div></div><strong>${fmt(a.value)}</strong></div>`).join(''):'No records for this filter'}</div><div style="margin-top:20px" class="note"><strong>What is changing?</strong> Approving leave changes absence status; onboarding a candidate adds a worker record and updates FTE/headcount rollups automatically.</div></div>
 <div class="card"><div class="stat-label">Combined ${esc(x.metric)}</div><div class="stat-num" style="font:800 36px Manrope;margin:12px 0">${fmt(x.total)}</div><div class="note">Current permitted sample data, computed directly from the application database.</div><div style="margin-top:22px">${table(['Group','Value'],x.items,a=>`<tr><td><strong>${esc(a.label)}</strong></td><td>${fmt(a.value)}</td></tr>`)}</div></div></div>`}
async function optional(){const expenses=await api('/expenses');let cases=[];if(isHR())cases=await api('/cases');return `${pageHead('Additional-cost capabilities','OPTIONAL / NOT IN BASE SOFTWARE ARR','These are working prototype extensions and remain separately scoped/licensed in the Sheffield response.')}
 <div class="grid three"><div class="card"><span class="badge warn">Additional cost</span><h3 style="margin-top:13px">Claims & expenses</h3><p class="small muted">Submit and review expense claims from employee to manager.</p><button style="margin-top:16px" class="btn light small" data-act="new-expense">+ Submit claim</button></div><div class="card"><span class="badge warn">Additional cost</span><h3 style="margin-top:13px">HR case management</h3><p class="small muted">Controlled People Services case tracking with assigned owner and closure.</p>${isHR()?'<button style="margin-top:16px" class="btn light small" data-act="new-case">+ Open HR case</button>':'<div class="micro muted" style="margin-top:19px">HR access only</div>'}</div><div class="card"><span class="badge warn">Additional cost</span><h3 style="margin-top:13px">Advanced insights</h3><p class="small muted">Custom analytics extensions, modelled above the baseline reporting features.</p><button style="margin-top:16px" class="btn light small" data-page="reports">Explore reporting</button></div></div>
 <div class="card" style="margin-top:20px"><h3>Expense claims</h3>${table(['Employee','Category','Amount','Detail','State','Action'],expenses,x=>`<tr><td><strong>${esc(x.employee)}</strong></td><td>${esc(x.category)}</td><td>${money(x.amount)}</td><td>${esc(x.detail)}</td><td>${status(x.status)}</td><td>${x.status==='Submitted'&&isManager()?`<div class="inline-actions"><button class="btn light small" data-act="expense-decision" data-id="${x.id}" data-choice="Approved">Approve</button><button class="btn danger small" data-act="expense-decision" data-id="${x.id}" data-choice="Rejected">Reject</button></div>`:'--'}</td></tr>`)}</div>
 ${isHR()?`<div class="card" style="margin-top:20px"><h3>Optional HR case register</h3>${table(['Case','Employee','Category','State','Action'],cases,x=>`<tr><td><strong>${esc(x.title)}</strong></td><td>${esc(x.employee)}</td><td>${esc(x.category)}</td><td>${status(x.status)}</td><td>${x.status==='Open'?`<button class="btn small light" data-act="case-close" data-id="${x.id}">Close case</button>`:'--'}</td></tr>`)}</div>`:''}`}
async function integrations(){const x=await api('/integrations');return `${pageHead('Integration & recovery console','MOCK ADAPTER / AUDITABLE EXCEPTIONS','See controlled integration events, simulate a failure and retry with exactly-once local event identifiers.')}
 <div class="note attention">These adapters are local mocks. Entra ID/MFA, Outlook, corporate finance, CRM and payment providers have not been connected. A green Delivered status here means the mock adapter acknowledged the event, not the actual external system.</div>
 <div class="grid three" style="margin-top:16px">${x.systems.map(s=>`<div class="card tight"><span class="badge blue">${esc(s.method)}</span><h3 style="margin-top:10px">${esc(s.name)}</h3><p class="small muted">${esc(s.description)}</p></div>`).join('')}</div><div class="card" style="margin-top:20px"><div class="section-top"><h2>Integration event queue</h2><span>Force failure then retry successfully</span></div>${table(['System / event','Entity','Attempts','State','Latest exception','Action'],x.events,e=>`<tr><td><strong>${esc(e.system)}</strong><div class="micro muted">${esc(e.event)}</div></td><td>#${e.entity_id}</td><td>${e.attempts}</td><td>${status(e.status)}</td><td>${esc(e.error||'--')}</td><td>${e.status!=='Delivered'&&state.user.role==='admin'?`<span class="inline-actions"><button class="btn light small" data-act="integration-process" data-id="${e.id}">Process</button><button class="btn danger small" data-act="integration-fail" data-id="${e.id}">Inject failure</button></span>`:'--'}</td></tr>`)}</div>`}
async function messages(){const m=await api('/messages');return `${pageHead('Private message centre','INTERNAL COMMUNICATION / BCC-STYLE','Recipients are private to each other, with optional forced notification recorded for local demo only.',`${['admin','hr','manager','service','recruiter','learning'].includes(state.user.role)?'<button class="btn primary" data-act="new-message">+ Compose message</button>':''}`)}
 <div class="grid two"><div class="card"><div class="eyebrow">PRIVACY BY DESIGN</div><h3>Private recipient list</h3><p class="small muted">To behaves like BCC: recipients receive a message but cannot view other recipient identities.</p></div><div class="card"><div class="eyebrow">COMMUNICATION CONTROLS</div><h3>255 / 4,000-character limits</h3><p class="small muted">Subject is limited to 255 characters, message to 4,000. Notification override is queued, not emailed.</p></div></div>
 <div class="card" style="margin-top:20px"><h3>My inbox</h3>${table(['Subject','From','Received','Status','Action'],m,x=>`<tr><td><strong>${esc(x.subject)}</strong><div class="small muted">${esc(x.body.slice(0,130))}${x.body.length>130?'...':''}</div></td><td>${esc(x.sender)}</td><td>${ago(x.created)}</td><td>${status(x.read_at?'Read':'Unread')}</td><td>${!x.read_at?`<button class="btn light small" data-act="message-read" data-id="${x.id}">Mark read</button>`:'--'}</td></tr>`)}</div>`}
const SCRIPT=[
  ['00:00 - 03:00','Platform orientation','Explain role-based workspaces, source of truth, 8,000-person baseline versus synthetic sample records.','overview'],
  ['03:00 - 09:00','Use case 1: annual leave','Aisha submits annual leave, Helen approves; return as Aisha and show updated remaining balance and audit.','leave'],
  ['09:00 - 15:00','Use case 2: organisation structure','Explore post, grade, FTE, cost centre, hierarchy and manager/team roll-up.','org'],
  ['15:00 - 25:00','Use case 3: applicant to employee','Create/publish vacancy, apply as public candidate, shortlist, self-select/reschedule video slot, score interview, offer and onboard.','recruit'],
  ['25:00 - 32:00','Use case 4: document lifecycle','Upload a sample record, inspect employee visibility, archive it and discuss retention-based purge.','documents'],
  ['32:00 - 39:00','Use case 5: HR process','Create HR check, complete as assignee, review hand-off and audit. Demonstrate optional cases distinctly.','tasks'],
  ['39:00 - 46:00','Use case 6: management information','Change report grouping, filter by service, drill into metrics and export CSV.','reports'],
  ['46:00 - 50:00','Architecture and closing','Discuss learning, illustrative payroll, controlled integration failure/retry, Entra/UK payroll boundaries and Q&A.','integrations']
];
async function guide(){return `${pageHead('Presenter run-of-show','SHEFFIELD / 45-50 MINUTE LIVE DEMO','The script below is also provided as a standalone presenter guide inside the ZIP.',`<button class="btn primary" data-act="reset-demo">Reset sample for a clean take</button>`)}
 <div class="hero-strip"><div><h2>Six connected stories. One employee record.</h2><p>Always narrate what just changed in the shared system, and show the next persona receiving the hand-off.</p></div><button class="btn" data-page="overview">Back to workspace</button></div>
 <div class="story-timeline">${['Leave','Structure','Recruit','Records','HR process','Insights'].map((x,i)=>`<div class="story-part"><strong>${i+1}</strong><small>${x}</small></div>`).join('')}</div>
 <div class="card" style="margin-top:20px"><h2>Demo sequence and talking points</h2><p class="card-sub">Change persona from the lower-left account control at each hand-off.</p>${SCRIPT.map((a,i)=>`<div style="display:grid;grid-template-columns:120px 1fr auto;align-items:start;gap:14px;border-bottom:1px solid #edf1f5;padding:19px 0"><div class="badge blue">${a[0]}</div><div><h3>${i+1}. ${a[1]}</h3><p class="small muted">${a[2]}</p></div><button class="btn ghost small" data-page="${a[3]}">Open</button></div>`).join('')}</div>
 <div class="note attention" style="margin-top:20px">For a video, use a fresh dataset (Reset), hide test emails/access tokens, switch personas deliberately and avoid portraying a simulated system as the live Oracle Fusion Cloud product.</div>`}
async function matrix(){const x=await api('/capabilities');return `${pageHead('Requirements coverage','SOURCE TRACEABILITY / RESPONSE TABLE 1','All 47 Sheffield processes are captured using the submitted commercial classification. Demo-depth notes identify prototype boundaries.')}
 <div class="grid three"><div class="card stat"><div class="stat-label">Submitted requirement processes</div><div class="stat-num">47</div></div><div class="card stat"><div class="stat-label">Proposed baseline</div><div class="stat-num">43</div></div><div class="card stat"><div class="stat-label">Additional-cost scope</div><div class="stat-num">4</div></div></div><div class="card" style="margin-top:20px">${table(['#','Capability area','Requirement','PCL proposal','Demo evidence'],x,a=>`<tr><td>${a.id}</td><td>${esc(a.area)}</td><td><strong>${esc(a.process)}</strong></td><td>${status(a.proposal)}</td><td><span class="micro muted">${esc(a.demo_depth)}</span><div class="micro muted">${esc(a.demo_note)}</div></td></tr>`)}</div>`}
async function audit(){const a=await api('/audit');return `${pageHead('Audit evidence','GOVERNANCE / ACTION TRACEABILITY','Every significant mutation captures actor, operation, entity and UTC timestamp.')}
 <div class="card">${table(['Timestamp (UTC)','Actor','Action','Record','Evidence'],a,r=>`<tr><td>${ago(r.created)}</td><td><strong>${esc(r.actor)}</strong></td><td>${esc(r.action)}</td><td>${esc(r.entity)} #${r.entity_id}</td><td>${esc(r.detail||'--')}</td></tr>`)}</div>`}
function formWrap(kind,html,button='Save changes'){return `<form data-form="${kind}" class="form-stack">${html}<div class="form-actions"><button class="btn ghost" type="button" data-act="close-modal">Cancel</button><button type="submit" class="btn primary">${button}</button></div></form>`}
const field=(label,name,placeholder='',required=true,more='')=>`<label>${label}<input name="${name}" placeholder="${esc(placeholder)}" ${required?'required':''} ${more}></label>`;
function candidateLookupModal(){openModal('Track your application','Use the private access token from your application submission.',formWrap('candidate-lookup',field('Access token','token',state.candidateToken),'Track application'))}
async function action(name,d){let after=true;
 switch(name){
 case 'refresh':return render();
 case 'close-modal':closeModal();return;
 case 'public-careers':state.public=true;await render();return;
 case 'public-exit':if(state.user){state.public=false;state.page='recruit';await render()}else await showLogin();return;
 case 'clear-candidate':state.candidateToken='';localStorage.removeItem('sheffield_candidate_token');return render();
 case 'profile-edit':{const data=await api('/profile');openModal('Update personal details','Your changes are recorded against your own employee record.',formWrap('profile',`<label>Contact telephone<input name="phone" value="${esc(data.profile.phone)}" maxlength="50"></label><label>Postal address<input name="address" value="${esc(data.profile.address)}" maxlength="280"></label><label>Emergency contact<input name="emergency_contact" value="${esc(data.profile.emergency_contact)}" maxlength="140"></label>`,'Save contact details'));return;}
 case 'new-time':openModal('Submit a weekly timesheet','A manager reviews submitted hours; approved records enter the mock finance queue.',formWrap('time',`<label>Week commencing (Monday)<input name="week_start" type="date" value="${lastMonday()}" required></label><label>Total hours worked<input type="number" name="hours" min="0.25" max="65" step="0.25" value="37.5" required></label>`,'Submit hours'));return;
 case 'time-decision':await post(`/time/${d.id}/decision`,{decision:d.choice});toast('Timesheet '+d.choice.toLowerCase());break;
 case 'new-leave':openModal('Request an absence','Annual leave is calculated using weekdays; approved time updates your balance.',formWrap('leave',`<div class="field-grid"><label>Absence type<select name="leave_type"><option>Annual</option><option>Carer</option><option>Discretionary</option><option>Trade union</option><option>Sickness</option><option>Other</option></select></label><label>Start date<input type="date" name="start" value="${later(10)}" required></label><label>End date<input type="date" name="ending" value="${later(11)}" required></label>${field('Reason / notes','note','Optional reason',false)}</div>`,'Submit for approval'));return;
 case 'leave-decision':await post(`/leave/${d.id}/decision`,{decision:d.choice});toast('Leave request '+d.choice.toLowerCase());break;
 case 'new-vacancy':openModal('Create a vacancy','Short, single-page journey. A recruiter can publish the draft when ready.',formWrap('vacancy',`<div class="field-grid">${field('Job title','title','e.g. Housing Services Adviser')}${field('Service / department','department','e.g. Adult Social Care')}${field('Grade','grade','G6',false)}${field('Salary display','salary','GBP 30,000 - 34,000',false)}${field('Location','location','Sheffield / hybrid',false)}<label>Closing date<input name="closing" type="date" value="${later(30)}" required></label><label class="wide">Job summary<textarea name="summary" placeholder="Describe the role and its public-service purpose" maxlength="1200" required></textarea></label><label class="check-row wide"><input type="checkbox" name="cover_required">Require a cover letter from applicants</label></div>`,'Create draft vacancy'));return;
 case 'edit-vacancy':{const v=(await api('/vacancies')).find(x=>x.id===Number(d.id));if(!v)throw Error('Vacancy no longer available');openModal('Edit published vacancy','Edits are permitted and versioned, including after posting.',formWrap('edit-vacancy',`<input name="id" type="hidden" value="${v.id}"><div class="field-grid"><label>Job title<input name="title" value="${esc(v.title)}" required></label><label>Grade<input name="grade" value="${esc(v.grade)}"></label><label>Salary band<input name="salary" value="${esc(v.salary)}"></label><label>Closing date<input type="date" name="closing" value="${esc(v.closing)}" required></label><label class="wide">Role summary<textarea name="summary" maxlength="1200">${esc(v.summary)}</textarea></label><label class="check-row wide"><input type="checkbox" name="cover_required" ${v.cover_required?'checked':''}>Cover letter is mandatory</label></div>`,'Save revision'));return;}
 case 'publish':await post(`/vacancies/${d.id}/publish`);toast('Vacancy published in public careers');break;
 case 'close-vacancy':if(!confirm('Close this vacancy to new applications?'))return;await post(`/vacancies/${d.id}/close`);toast('Vacancy closed');break;
 case 'apply':openModal('Apply - '+(d.title||'Council vacancy'),'Submit an application, then save the token to track progress and schedule interviews.',formWrap('apply',`<input type="hidden" name="vacancy_id" value="${esc(d.id)}"><div class="field-grid">${field('Full name','name','e.g. Maya Evans')}${field('Email address','email','maya@example.com',true,'type="email"')}<label class="wide">Personal statement<textarea name="statement" maxlength="2000" placeholder="How do your skills match this role?" required></textarea></label><label class="wide">Cover letter ${Number(d.cover)?'(required)':'(optional)'}<textarea name="cover_letter" maxlength="2000" ${Number(d.cover)?'required':''}></textarea></label><label class="wide">Application source<select name="source"><option>Council careers</option><option>External job board</option><option>Referral</option></select></label></div>`,'Submit application'));return;
 case 'schedule':openModal('Choose your interview slot','You can return and reschedule while the application is in the interview stage.',formWrap('interview',`<label>Interview time<input type="datetime-local" name="slot" value="${later(7)}T11:00" required></label><label>Interview format<select name="type"><option>Video</option><option>In-person</option></select></label>`,'Confirm interview'));return;
 case 'withdraw':if(!confirm('Withdraw this application? This cannot be undone.'))return;await post('/candidate/'+encodeURIComponent(state.candidateToken)+'/withdraw');toast('Application withdrawn');break;
 case 'app-stage':if(d.stage==='Interview Completed'){openModal('Record interview outcome','Score and substantive written feedback are mandatory for fair, auditable decisions.',formWrap('app-stage',`<input type="hidden" name="id" value="${d.id}"><input type="hidden" name="stage" value="${esc(d.stage)}"><label>Interview score 0 to 5<input name="score" type="number" min="0" max="5" step="1" required></label><label>Detailed panel feedback<textarea name="feedback" maxlength="900" placeholder="Describe evidence against selection criteria" required></textarea></label>`,'Save interview outcome'));return;}
 if(d.stage==='Onboarded'&&!confirm('Create the employee record and linked onboarding tasks?'))return;await post(`/applications/${d.id}/stage`,{stage:d.stage});toast('Application updated to '+d.stage);break;
 case 'new-document':{const people=await api('/people');openModal('Upload employee document','Files are private, classified and governed by a retention date. Maximum 5 MB.',formWrap('document',`<label>Employee<select name="employee_id">${selectOpts(isHR()?people:people.filter(x=>x.id===state.user.id))}</select></label><label>Document classification<select name="doc_type"><option>Employment</option><option>Signed declaration</option><option>Identity verification</option><option>Learning certificate</option><option>Payroll document</option></select></label><label>Retention until<input type="date" name="retention_until" value="2033-12-31" required></label><label>File (PDF, DOCX, TXT, PNG, JPEG)<input type="file" name="file" accept=".pdf,.txt,.docx,.png,.jpg,.jpeg" required></label>`,'Upload document'));return;}
 case 'doc-expire':if(!confirm('Set this ARCHIVED demo record to yesterday for retention-purge demonstration? No production retention rules will be changed.'))return;await post(`/documents/${d.id}/simulate-expiry`);toast('Demo retention expiry simulated; run eligible purge');break;
 case 'archive':if(!confirm('Archive this document?'))return;await post(`/documents/${d.id}/archive`);toast('Document archived');break;
 case 'purge':if(!confirm('Purge archived documents whose retention dates have passed?'))return;{const x=await post('/documents/purge');toast(x.purged+' eligible documents purged');break;}
 case 'app-message':openModal('Candidate correspondence','Delivered to the private candidate tracker inbox within this demo. It does not send a real email.',formWrap('app-message',`<input type="hidden" name="id" value="${d.id}"><label>Subject<input name="subject" maxlength="255" required placeholder="Update on your application"></label><label>Message<textarea name="body" maxlength="4000" rows="5" required></textarea></label>`,'Send to candidate portal'));return;
 case 'new-task':{const people=await api('/people');openModal('Assign a guided HR task','The assignee receives an actionable work item and completion is logged.',formWrap('task',`<div class="field-grid">${field('Task title','title','e.g. Verify signed declaration')}<label>Task type<select name="kind"><option>HR Process</option><option>HR Check</option><option>Onboarding</option><option>Learning</option></select></label><label>Assigned to<select name="assigned_to">${selectOpts(people)}</select></label><label>Deadline<input name="due" type="date" value="${later(7)}" required></label><label class="wide">Instructions<textarea name="notes" maxlength="700"></textarea></label></div>`,'Assign task'));return;}
 case 'task-done':await post(`/tasks/${d.id}/complete`);toast('Task completed and audited');break;
 case 'enrol':await post(`/learning/${d.id}/enrol`);toast('Course booking confirmed');break;
 case 'learning-complete':await post(`/learning/${d.id}/complete`);toast('Completion entered in learning record');break;
 case 'new-payroll':openModal('Create illustrative payroll','A draft run calculates synthetic monthly pay. Finalisation makes payslips visible.',formWrap('payroll',`<label>Payroll period (YYYY-MM)<input name="period" type="month" value="${new Date().toISOString().slice(0,7)}" required></label><div class="note attention">Demonstration only: fixed 18% example deduction. Never use this result to pay workers or file UK statutory returns.</div>`,'Calculate payroll'));return;
 case 'pay-final':if(!confirm('Finalise this illustrative payroll and publish demo payslips?'))return;await post(`/payroll/${d.id}/finalise`);toast('Demo payslips published');break;
 case 'csv':{const url='/api/reports/export?'+new URLSearchParams(state.report).toString();window.location.href=url;toast('CSV export requested');return;}
 case 'new-expense':openModal('Submit an expense claim','Optional module, separately scoped from the Sheffield baseline.',formWrap('expense',`<label>Category<select name="category"><option>Travel</option><option>Training</option><option>Subsistence</option><option>Other</option></select></label>${field('Claim amount (GBP)','amount','42.50',true,'type="number" step="0.01" min="0.01" max="5000"')}<label>Business reason<textarea name="detail" maxlength="500" required></textarea></label>`,'Submit claim'));return;
 case 'expense-decision':await post(`/expenses/${d.id}/decision`,{decision:d.choice});toast('Expense '+d.choice.toLowerCase());break;
 case 'new-case':{const p=await api('/people');openModal('Open People Services case','Optional case-management capability, not included in the base software subscription.',formWrap('case',`<label>Employee<select name="employee_id">${selectOpts(p)}</select></label><label>Case category<select name="category"><option>Attendance</option><option>Employee relations</option><option>Disciplinary</option><option>Other</option></select></label>${field('Case title','title','Restricted HR record')}<label>Case details<textarea name="details" maxlength="1800" required></textarea></label>`,'Create restricted case'));return;}
 case 'case-close':await post(`/cases/${d.id}/close`);toast('HR case closed');break;
 case 'integration-process':{const x=await post(`/integrations/${d.id}/process`,{fail:false});toast('Mock adapter: '+x.status);break;}
 case 'integration-fail':{const x=await post(`/integrations/${d.id}/process`,{fail:true});toast('Simulated integration timeout captured');break;}
 case 'new-message':{const p=await api('/people');openModal('Compose private message','To is BCC-style; all recipient identities remain hidden from other recipients.',formWrap('message',`<label>To - private recipients<span class="small muted">Select recipients below</span><span class="checkgrid">${p.filter(x=>x.id!==state.user.id).map(x=>`<label><input type="checkbox" name="recipient" value="${x.id}">${esc(x.name)}</label>`).join('')}</span></label><label>Subject (maximum 255 characters)<input name="subject" maxlength="255" required></label><label>Message (maximum 4,000 characters)<textarea name="body" maxlength="4000" rows="7" required></textarea></label><label class="check-row"><input type="checkbox" name="force_notify">Send notification irrespective of recipient preference (mock queue only)</label><div class="note">Draft long messages outside the app before pasting. Live email delivery is not configured.</div>`,'Send private message'));return;}
 case 'message-read':await post(`/messages/${d.id}/read`);toast('Message marked read');break;
 case 'reset-demo':if(state.user.role!=='admin'){toast('Sign in as Sofia Bennett to reset the demo.',true);return;}openModal('Restore demonstration records','Danger: this permanently clears local demo transactions and uploaded records.',formWrap('reset',field('Confirmation phrase','confirm','RESET DEMO'),'Reset all demo data'));return;
 default:toast('This action is unavailable',true);return;
 }if(after)await render();}

async function submit(kind,form){const p=formData(form);let x;
 switch(kind){
 case 'profile':x=await post('/profile',p);toast('Personal details updated');break;
 case 'time':x=await post('/time',p);toast('Timesheet submitted for approval');break;
 case 'leave':x=await post('/leave',p);toast(`Leave request #${x.id} submitted (${x.days} weekdays)`);break;
 case 'vacancy':x=await post('/vacancies',p);toast(`Vacancy #${x.id} saved as Draft`);break;
 case 'edit-vacancy':{const id=p.id;delete p.id;x=await post(`/vacancies/${id}/update`,p);toast('Vacancy revised to version '+x.revision);break;}
 case 'apply':{const id=p.vacancy_id;delete p.vacancy_id;x=await post('/apply/'+id,p);state.candidateToken=x.access_token;localStorage.setItem('sheffield_candidate_token',x.access_token);toast('Application received: #'+x.id);break;}
 case 'candidate-lookup':{x=await api('/candidate/'+encodeURIComponent(p.token.trim()));state.candidateToken=p.token.trim();localStorage.setItem('sheffield_candidate_token',state.candidateToken);toast('Application found: '+x.stage);break;}
 case 'interview':x=await post('/candidate/'+encodeURIComponent(state.candidateToken)+'/interview',p);toast('Interview preference saved; calendar event queued');break;
 case 'app-stage':{const id=p.id;delete p.id;x=await post(`/applications/${id}/stage`,p);toast('Interview outcome saved with feedback');break;}
 case 'app-message':{const id=p.id;delete p.id;x=await post(`/applications/${id}/message`,p);toast('Portal correspondence saved; no real email sent');break;}
 case 'task':x=await post('/tasks',p);toast('Task #'+x.id+' assigned');break;
 case 'document':{const fd=new FormData(form);const qs=new URLSearchParams({employee_id:fd.get('employee_id'),doc_type:fd.get('doc_type'),retention_until:fd.get('retention_until')});const f=fd.get('file');if(!f?.size)throw Error('Select a file before uploading');const body=new FormData();body.append('file',f);x=await api('/documents?'+qs.toString(),{method:'POST',body});toast('Document saved with retention rules');break;}
 case 'payroll':x=await post('/payroll/run',p);toast('Draft calculation: '+x.headcount+' people');break;
 case 'expense':x=await post('/expenses',p);toast('Expense claim #'+x.id+' submitted');break;
 case 'case':x=await post('/cases',p);toast('HR case #'+x.id+' created');break;
 case 'message':{const recipientIds=Array.from(form.querySelectorAll('input[name="recipient"]:checked')).map(t=>Number(t.value));x=await post('/messages',{recipients:recipientIds,subject:p.subject,body:p.body,force_notify:!!p.force_notify});toast(`Message queued privately for ${x.recipient_count} recipients; no emails sent`);break;}
 case 'reset':x=await post('/demo/reset',p);toast('Initial demonstration records restored');break;
 case 'report':state.report={group:p.group,metric:p.metric,filter:p.filter};return render();
 default:throw Error('Unknown form action');
 }
 closeModal();if(kind==='apply'||kind==='candidate-lookup')state.public=true;await render();}

document.addEventListener('click',async e=>{const page=e.target.closest('[data-page]');if(page){e.preventDefault();go(page.dataset.page);return;}const act=e.target.closest('[data-act]');if(!act)return;e.preventDefault();try{act.disabled=true;await action(act.dataset.act,act.dataset)}catch(err){toast(err.message,true)}finally{act.disabled=false}});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const b=form.querySelector('[type=submit]');try{if(b)b.disabled=true;await submit(form.dataset.form,form)}catch(err){toast(err.message,true)}finally{if(b)b.disabled=false}});
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button');try{btn.disabled=true;const x=await post('/login',{user_id:Number($('personaSelect').value),pin:$('loginPin').value});state.user=x.user;state.public=false;state.page='overview';setLayout();await render();toast('Signed in as '+x.user.name)}catch(err){toast(err.message,true)}finally{btn.disabled=false}});
$('publicLaunch').addEventListener('click',async()=>{state.public=true;state.page='recruit';setLayout();await render()});
$('switchPerson').addEventListener('click',async()=>{await post('/logout');await showLogin()});
$('refresh').addEventListener('click',()=>render());$('mobileMenu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
boot();
